local BedMaker = {}
local PRODUCTS = {
    simple_wooden_bed = { name = "Preprosta lesena postelja", woodCost = 4, woolCost = 2, time = 5, cost = 100, beauty = 22, happiness = 2, comfort = 25, description = "Preprosta lesena postelja za hišo." },
    carved_oak_bed = { name = "Izrezljana hrastova postelja", woodCost = 4, woolCost = 2, linenCost = 1, time = 8, cost = 280, beauty = 38, happiness = 3, comfort = 40, prestige = 2, description = "Izrezljana hrastova postelja za trgovce." },
    silver_trimmed_bed = { name = "Srebrnoobrobljena postelja", woodCost = 4, silverCost = 1, woolCost = 2, linenCost = 1, time = 11, cost = 680, beauty = 52, happiness = 4, comfort = 55, prestige = 6, description = "Srebrnoobrobljena postelja za plemiče." },
    gold_inlaid_bed = { name = "Zlatovložena postelja", woodCost = 5, goldCost = 1, silverCost = 1, woolCost = 2, linenCost = 1, time = 15, cost = 1500, beauty = 65, happiness = 5, comfort = 70, prestige = 14, description = "Zlatovložena postelja za visoke plemiče." },
    silk_canopy_bed = { name = "Svilna nebotična postelja", woodCost = 5, goldCost = 2, silverCost = 1, silkCost = 2, woolCost = 2, linenCost = 1, jewelCost = 1, time = 19, cost = 3200, beauty = 80, happiness = 7, comfort = 85, prestige = 28, description = "Nebotična postelja z draguljem za visoko plemstvo." },
    royal_grand_bed = { name = "Kraljevski veliki postelja", woodCost = 7, goldCost = 3, silverCost = 2, silkCost = 3, woolCost = 3, linenCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 7000, beauty = 95, happiness = 13, comfort = 100, prestige = 60, description = "Velika kraljevska postelja z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    bed_workshop = { name = "Posteljna delavnica", cost = { gold = 280, wood = 180, stone = 100, wool = 6 }, upkeep = 6, qualityBonus = 5 },
    bedding_loft = { name = "Ležišna podstrešje", cost = { gold = 1000, wood = 340, stone = 240, silver = 6, linen = 6 }, upkeep = 23, qualityBonus = 18 },
    master_bed_atelier = { name = "Mojstrski posteljni atelje", cost = { gold = 2800, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_bed_palace = { name = "Kraljevska posteljna palača", cost = { gold = 11800, wood = 600, stone = 760, gold = 75, jewel = 18 }, upkeep = 235, qualityBonus = 55, prestigeBonus = 50 },
}
BedMaker.woodStock = 22; BedMaker.woolStock = 14; BedMaker.linenStock = 10; BedMaker.silkStock = 8; BedMaker.silverStock = 6; BedMaker.goldStock = 6; BedMaker.jewelStock = 4; BedMaker.pearlStock = 4
BedMaker.productStock = {}; BedMaker.buildings = {}; BedMaker.maker = nil; BedMaker.activeMaking = {}; BedMaker.totalProducts = 0; BedMaker.dayTimer = 0
function BedMaker.init() BedMaker.woodStock=22; BedMaker.woolStock=14; BedMaker.linenStock=10; BedMaker.silkStock=8; BedMaker.silverStock=6; BedMaker.goldStock=6; BedMaker.jewelStock=4; BedMaker.pearlStock=4; BedMaker.productStock={}; BedMaker.buildings={}; BedMaker.maker=nil; BedMaker.activeMaking={}; BedMaker.totalProducts=0; BedMaker.dayTimer=0; print("[BedMaker] Royal Bed Maker System initialized (6 products, 4 buildings)") end
function BedMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BedMaker.maker={name=n or ("Posteljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Posteljar najet: %s (spretnost: %d)",BedMaker.maker.name,s),"success") end; return true end
function BedMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BedMaker.build(id) local ok,e=BedMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BedMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BedMaker.getQualityBonus() local b=0; for _,bd in ipairs(BedMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BedMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BedMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.woolCost and BedMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.linenCost and BedMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.silkCost and BedMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.silverCost and BedMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BedMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BedMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BedMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BedMaker.buildings==0 then return false,"Potrebna posteljna delavnica" end; if not BedMaker.maker then return false,"Potreben posteljar" end; return true end
function BedMaker.make(pt,qty) qty=qty or 1; local ok,e=BedMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BedMaker.woodStock=BedMaker.woodStock-d.woodCost*qty end; if d.woolCost then BedMaker.woolStock=BedMaker.woolStock-d.woolCost*qty end; if d.linenCost then BedMaker.linenStock=BedMaker.linenStock-d.linenCost*qty end; if d.silkCost then BedMaker.silkStock=BedMaker.silkStock-d.silkCost*qty end; if d.silverCost then BedMaker.silverStock=BedMaker.silverStock-d.silverCost*qty end; if d.goldCost then BedMaker.goldStock=BedMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BedMaker.jewelStock=BedMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BedMaker.pearlStock=BedMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BedMaker.maker then t=math.max(1,t-math.floor(BedMaker.maker.skill/12)) end; table.insert(BedMaker.activeMaking,{id="bed_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,comfort=d.comfort or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BedMaker.completeMaking(m) local q=1.0+(BedMaker.getQualityBonus()/100); if BedMaker.maker then q=q+(BedMaker.maker.skill/140) end; q=math.min(2.5,q); BedMaker.productStock[m.productType]=(BedMaker.productStock[m.productType] or 0)+m.quantity; BedMaker.totalProducts=BedMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BedMaker.maker then BedMaker.maker.itemsMade=BedMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BedMaker.maker.skill=math.min(100,BedMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Postelja izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bed.completed",{productName=m.productName,beauty=m.beauty,comfort=m.comfort,prestige=m.prestige,happiness=m.happiness}) end end
function BedMaker.update(dt) if not _G.state then return end; BedMaker.dayTimer=BedMaker.dayTimer+dt; if BedMaker.dayTimer>=30 then BedMaker.dayTimer=0; for i=#BedMaker.activeMaking,1,-1 do local m=BedMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BedMaker.completeMaking(m); table.remove(BedMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BedMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BedMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BedMaker.getStats() return {woodStock=BedMaker.woodStock,woolStock=BedMaker.woolStock,linenStock=BedMaker.linenStock,silkStock=BedMaker.silkStock,silverStock=BedMaker.silverStock,goldStock=BedMaker.goldStock,jewelStock=BedMaker.jewelStock,pearlStock=BedMaker.pearlStock,productStock=BedMaker.productStock,numBuildings=#BedMaker.buildings,hasMaker=BedMaker.maker~=nil,makerName=BedMaker.maker and BedMaker.maker.name or "—",makerSkill=BedMaker.maker and BedMaker.maker.skill or 0,activeMaking=#BedMaker.activeMaking,totalProducts=BedMaker.totalProducts} end
return BedMaker
